mapper.select:
SELECT COUNT(flrc_type) AS SumTotal, COUNT(flrc_type = 3 OR NULL OR flrc_type = 6 OR flrc_type = 7 ) AS Inland, COUNT(flrc_type = 1 OR NULL OR flrc_type = 4 OR flrc_type = 9) AS InterNational, COUNT(flrc_type = 2 OR NULL OR flrc_type = 5 OR flrc_type = 8) AS Lcountry FROM T_FUEL_RECPT WHERE DATE_FORMAT(flrc_rec_cre_time,'%Y-%m-%d')=CURDATE()
and flrc_aptarea_code=#{staffAptareaCode}
and flrc_airport_code=#{staffAirportCode}

SELECT SUM(flrc_fuel_vol) AS flrcFuelVol, SUM(flrc_quantity/1000) AS flrcQuantity FROM T_FUEL_RECPT WHERE DATE_FORMAT(flrc_rec_cre_time,'%Y-%m-%d')=CURDATE()
and flrc_aptarea_code=#{staffAptareaCode}
and flrc_airport_code=#{staffAirportCode}

SELECT flgt_regn AS aircraftID, flgt_vialc AS airRoute,flgt_flno AS flightNA,
       flgt_flti AS rangeA  ,flgt_a_atot AS timeA,flgt_adid AS statusA,
       flgt_flno AS flightND ,flgt_flti AS rangeD,flgt_gate AS gateD
FROM T_FLIGHT
WHERE flgt_airport_code=#{flgtAirportCode}
  AND flgt_adid='A' AND flgt_flno=#{flightNA}
  AND flgt_id=#{aircraftID}
  AND flgt_flop=CURDATE()
    limit 1

SELECT flgt_regn AS aircraftID, flgt_vialc AS airRoute,flgt_flno AS flightNA,
       flgt_flti AS rangeA  ,flgt_a_atot AS timeA, flgt_adid AS statusA,
       flgt_flno AS flightND ,flgt_flti AS rangeD,flgt_gate AS gateD
FROM T_FLIGHT
WHERE flgt_airport_code=#{flgtAirportCode}
  AND flgt_adid='D' AND flgt_flno=#{flightND}
  AND flgt_id=#{aircraftID}
  AND flgt_flop=CURDATE()
    limit 1

