lrcDefuelStorage, a.flrc_supply_fuel_type AS flrcSupplyFuelType, a.flrc_remark AS flrcRemark, a.flrc_rapc3 AS flrcRapc3, a.flrc_rapcn AS flrcRapcn, a.flrc_tanker_no AS flrcTankerNo, a.flrc_transport_mileage AS flrcTransportMileage, a.flrc_bus_type AS flrcBusType, a.settlement_rapc3 AS settlementRapc3, a.settlement_rapcn AS settlementRapcn, a.flrc_wkop_date AS flrcWkopDate, a.manual, a.flgt_id as flgtId, a.staff_scheduling_id AS staffSchedulingId, b.flgt_flop AS flgtFlop from T_FUEL_RECPT a left join T_FLIGHT b on a.flgt_id = b.flgt_id
