mapper.select:
SELECT tf.arcr_acname AS arcrName, tc.cstm_name AS cstmRegion, tc.cstm_region AS newCstmRegion, tc.cstm_num arcrCustomNum, tf.cnaf_update_time cnafUpdateTime FROM T_CUSTOM tc , T_FLIGHT_CODE tf WHERE TRIM(LEADING '0' FROM tf.arcr_custom_num) = TRIM(LEADING '0' FROM tc.cstm_num) and tf.arcr_regn=#{flgtRegn}
and tf.flno = #{flgtFlno}
and (tf.flno is null or tf.flno='')
and CURDATE() BETWEEN tf.arcr_start_date and tf.arcr_end_date and tf.del_flag=0 ORDER BY arcr_end_date DESC LIMIT 0,1

SELECT tf.arcr_acname AS arcrName, tc.cstm_name AS cstmRegion, tc.cstm_region AS newCstmRegion , tc.cstm_num arcrCustomNum FROM T_CUSTOM tc , T_FLIGHT_CODE_TEMPORARY tf WHERE TRIM(LEADING '0' FROM tf.arcr_custom_num) = TRIM(LEADING '0' FROM tc.cstm_num) and tf.arcr_regn=#{flgtRegn}
and tf.flno = #{flgtFlno}
and CURDATE() BETWEEN tf.arcr_start_date and tf.arcr_end_date ORDER BY arcr_end_date DESC LIMIT 0,1

